-- 13. TOURS
INSERT INTO tour (id_tour, nombre, descripcion, duracion_horas, dificultad, edad_minima, precio_persona, id_categoria, id_prestador) VALUES
(1, 'Valle de Cocora: Palma de Cera y Mirador', 'Caminata por el valle de la palma de cera, cruce de puentes colgantes y ascenso al mirador con vista al bosque de niebla. Incluye guía certificado y seguro.', 5.5, 'MEDIA', 8, 85000, 3, 14),
(2, 'Del Grano a la Taza: Tour del Café', 'Recorrido por una finca cafetera: siembra, recolección, beneficio, secado y tostión, con degustación de tres métodos de preparación.', 3.0, 'BAJA', 0, 70000, 4, 6),
(3, 'Cabalgata Cafetera por Filandia', 'Cabalgata guiada entre cafetales y guadua hasta el mirador, con parada para café de origen y almojábanas.', 4.0, 'MEDIA', 10, 90000, 2, 6),
(4, 'Canopy en el Bosque de Niebla', 'Circuito de nueve plataformas y tirolinas sobre bosque nativo con equipo certificado y guías de seguridad.', 2.5, 'MEDIA', 12, 110000, 2, 15),
(5, 'Avistamiento de Aves en el Río Navarco', 'Salida de madrugada con binoculares y listado de especies; se espera ver tucanes, colibríes y tángaras endémicas.', 4.0, 'BAJA', 6, 75000, 3, 16),
(6, 'Caminata al Cañón del Río Quindío', 'Descenso por sendero técnico hasta el cañón, con cruces de quebrada y baño en pozo natural. Requiere buen estado físico.', 6.0, 'ALTA', 14, 120000, 2, 15),
(7, 'Cascada de Santa Rita y Bosque de Guadua', 'Sendero ecológico a la cascada con explicación del ecosistema de guadua y refrigerio campesino.', 3.5, 'MEDIA', 8, 60000, 3, 14),
(8, 'Ruta Patrimonial de Filandia', 'Caminata por el centro histórico, balcones de la Calle del Tiempo Detenido y mirador Colina Iluminada.', 2.5, 'BAJA', 0, 45000, 1, 7),
(9, 'Museo del Oro Quimbaya y Centro Histórico', 'Visita guiada al museo de orfebrería precolombina y recorrido por la arquitectura republicana de Armenia.', 3.0, 'BAJA', 0, 50000, 1, 7),
(10, 'Pueblos Patrimonio en Jeep Willys', 'Recorrido en jeep por Circasia y Salento con paradas en miradores y talleres de artesanía.', 5.0, 'BAJA', 0, 95000, 1, 6),
(11, 'Experiencia Premium: Cata y Tostión', 'Taller de cata SCA y tostión en pequeño lote, con catador profesional y bolsa de café para llevar.', 4.0, 'BAJA', 14, 140000, 4, 6),
(12, 'Recolección de Café en Temporada de Cosecha', 'Participa en la cosecha junto a las familias caficultoras y aprende a seleccionar el grano maduro.', 3.0, 'MEDIA', 10, 80000, 4, 14),
(13, 'Senderismo Reserva Barbas–Bremen', 'Jornada completa por la reserva: bosque andino, humedal y observación de fauna. Se recomienda calzado de montaña.', 6.0, 'ALTA', 14, 105000, 3, 16),
(14, 'Ciclomontañismo por el Camino Nacional', 'Ruta en bicicleta de montaña por antiguos caminos de arriería, con bicicleta y casco incluidos.', 5.0, 'ALTA', 16, 130000, 2, 15),
(15, 'Orquídeas y Heliconias: Jardín Botánico', 'Recorrido interpretativo por colecciones de orquídeas, heliconias y el mariposario.', 2.5, 'BAJA', 0, 38000, 3, 16),
(16, 'Parque Temático Cafetero: Día Completo', 'Entrada al parque con recorrido por el museo del café, teatro de la tradición y atracciones culturales.', 7.0, 'BAJA', 0, 120000, 1, 7),
(17, 'Pijao Cittaslow: Pueblo Lento y Cafés de Origen', 'Caminata por el primer pueblo Cittaslow de Latinoamérica, con visita a cafés de origen y mirador.', 4.0, 'BAJA', 0, 65000, 1, 7),
(18, 'Observación de Estrellas en Finca Cafetera', 'Noche de astronomía con telescopios y chocolate caliente en una finca a 1.900 metros.', 2.0, 'BAJA', 6, 55000, 3, 14),
(19, 'Cuatrimotos por Fincas de La Tebaida', 'Recorrido en cuatrimoto por caminos rurales y fincas, con casco, gafas y briefing de seguridad.', 2.0, 'MEDIA', 16, 150000, 2, 15),
(20, 'Ruta Gastronómica Cafetera', 'Degustación en tres paradas: trucha, fríjoles con garra y postres de la región, maridados con café.', 3.5, 'BAJA', 0, 68000, 4, 6),
(21, 'Cacao y Chocolate Artesanal', 'Taller práctico del cacao al chocolate: tostado, molienda y moldeado en una finca agroturística.', 3.0, 'BAJA', 6, 58000, 1, 6),
(22, 'Parapente sobre el Paisaje Cafetero', 'Vuelo biplaza con piloto certificado desde el mirador; incluye video del vuelo.', 1.5, 'MEDIA', 16, 180000, 2, 14),
(23, 'Caminata Nocturna de Luciérnagas y Ranas', 'Sendero nocturno con linterna roja para observar luciérnagas, anfibios e insectos del bosque.', 2.0, 'BAJA', 8, 48000, 3, 16),
(24, 'Fotografía al Amanecer en la Palma de Cera', 'Salida de madrugada con fotógrafo guía para capturar la niebla y las palmas; incluye desayuno.', 6.5, 'MEDIA', 12, 125000, 3, 14);

